session_start();require_once __DIR__.'/dbconnection.php';$role=$_SESSION['portal_role']??'';$table=$role==='doctor'?'doctor':($role==='patient'?'patient':'admin');$id=(int)($_SESSION[$table.'id']??0);if(!$role||!$id){http_response_code(403);exit('Access denied');}$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$newpass=(string)($_POST['new_password']??'');$image='';$field=$table==='admin'?'adminname':($table==='doctor'?'doctorname':'patientname');$r=$con->query("SELECT * FROM `$table` WHERE ".($table==='admin'?'adminid':$table.'id')."=".$id)->fetch_assoc();$image=$r['profile_image']??'';if(!empty($_FILES['profile_image']['name'])){$ext=strtolower(pathinfo($_FILES['profile_image']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'],true)&&$_FILES['profile_image']['size']<3000000){$dir=__DIR__.'/professional_assets/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$file='profile_'.$table.'_'.$id.'_'.time().'.'.$ext;move_uploaded_file($_FILES['profile_image']['tmp_name'],$dir.'/'.$file);$image='professional_assets/uploads/'.$file;}else{$error='Invalid image file.';}}if(!$error){$pk=$table==='admin'?'adminid':$table.'id';$s=$con->prepare("UPDATE `$table` SET profile_image=? WHERE `$pk`=?");$s->bind_param('si',$image,$id);$s->execute();if($newpass!==''){$h=password_hash($newpass,PASSWORD_DEFAULT);$s=$con->prepare("UPDATE `$table` SET password=? WHERE `$pk`=?");$s->bind_param('si',$h,$id);$s->execute();}$msg='Profile updated.';}}
