?><!doctype html><html><head><meta charset="utf-8"><title>Profile</title><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"></head><body class="module-body"><div class="module-card narrow"><h1>My Profile</h1><?php if($msg):?><div class="success"><?php echo htmlspecialchars($msg);?></div><?php endif;?><?php if($error):?><div class="alert"><?php echo htmlspecialchars($error);?></div><?php endif;?><div class="profile-preview"><?php if(!empty($r['profile_image'])):?><img src="<?php echo htmlspecialchars($r['profile_image']);?>" alt="Profile"><?php else:?><div class="avatar large"><?php echo strtoupper(substr($r[$field],0,1));?></div><?php endif;?><b><?php echo htmlspecialchars($r[$field]);?></b><small><?php echo ucfirst($role);?></small></div><form method="post" enctype="multipart/form-data" class="form-grid"><label>Profile picture<input type="file" name="profile_image" accept="image/*"></label><label>New password (optional)<input type="password" name="new_password" minlength="6"></label><button class="primary-btn">Save profile</button></form></div></body></html>
